example:
-- 单行插入
INSERT INTO users (name, email, age) VALUES ('Alice', 'alice@ex.com', 25);

-- 多行插入
INSERT INTO posts (user_id, title, body) VALUES
  (1, 'Hello', 'First post'),
  (1, 'Second', 'Another post');

-- 事务批量插入（速度提升百倍）
BEGIN;
INSERT INTO users (name, email) VALUES ('Bob', 'bob@ex.com');
INSERT INTO users (name, email) VALUES ('Carol', 'carol@ex.com');
COMMIT;

-- INSERT OR REPLACE（若 email UNIQUE 冲突则替换）
INSERT OR REPLACE INTO users (name, email, age) VALUES ('Alice', 'alice@ex.com', 26);

-- 基本查询
SELECT name, email FROM users WHERE age > 20 ORDER BY age DESC;

-- 分页
SELECT * FROM posts ORDER BY id DESC LIMIT 10 OFFSET 20;

-- 搜索（注意 % 性能）
SELECT * FROM users WHERE name LIKE '%li%';

-- 列别名与表达式
SELECT name, age * 2 AS double_age FROM users;

-- 去重
SELECT DISTINCT age FROM users ORDER BY age;

-- 启用外键
PRAGMA foreign_keys = ON;

-- 带级联删除的外键
CREATE TABLE comments (
  id      INTEGER PRIMARY KEY,
  post_id INTEGER NOT NULL,
  content TEXT,
  FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);

-- 更新（仅 Alice 的年龄）
UPDATE users SET age = 26 WHERE name = 'Alice';

-- 删除前验证
SELECT * FROM posts WHERE user_id = 1;
DELETE FROM users WHERE id = 1;
-- 若外键 CASCADE，则 posts(id为1) 和 comments 也被删除

-- 统计
SELECT COUNT(*) AS total_users FROM users;
SELECT AVG(age) AS avg_age FROM users;
SELECT MIN(age), MAX(age) FROM users;

-- 分组统计
SELECT age, COUNT(*) AS count FROM users GROUP BY age HAVING count > 1;

-- 每个用户的文章数
SELECT u.name, COUNT(p.id) AS post_count
FROM users u LEFT JOIN posts p ON u.id = p.user_id
GROUP BY u.id;

-- GROUP_CONCAT
SELECT age, GROUP_CONCAT(name, ', ') AS names
FROM users GROUP BY age;

-- 创建索引
CREATE INDEX idx_posts_user ON posts(user_id);

-- 复合索引（最左前缀）
CREATE INDEX idx_users_name_age ON users(name, age);
-- 有效：WHERE name='Alice'
-- 有效：WHERE name='Alice' AND age>20
-- 无效（未用左前缀）：WHERE age>20

-- 查看查询计划
EXPLAIN QUERY PLAN SELECT * FROM users WHERE name LIKE 'A%';
EXPLAIN QUERY PLAN SELECT * FROM posts WHERE user_id = 1;

-- 列出所有索引
SELECT * FROM sqlite_master WHERE type = 'index';

-- 标量子查询
SELECT name,
  (SELECT COUNT(*) FROM posts WHERE posts.user_id = users.id) AS post_count
FROM users;

-- IN 子查询：有文章的用户
SELECT * FROM users WHERE id IN (SELECT DISTINCT user_id FROM posts);

-- EXISTS：等价写法（通常更快）
SELECT * FROM users u
WHERE EXISTS (SELECT 1 FROM posts p WHERE p.user_id = u.id);

-- NOT EXISTS：没有文章的用户
SELECT * FROM users u
WHERE NOT EXISTS (SELECT 1 FROM posts p WHERE p.user_id = u.id);

-- FROM 子查询：取前 5 个用户的最新文章
SELECT u.*, latest.title
FROM users u
LEFT JOIN (
  SELECT user_id, title, MAX(id) AS max_id
  FROM posts GROUP BY user_id
) latest ON u.id = latest.user_id
ORDER BY u.id LIMIT 5;

-- 创建视图
CREATE VIEW user_post_count AS
SELECT u.id, u.name, COUNT(p.id) AS cnt
FROM users u LEFT JOIN posts p ON u.id = p.user_id
GROUP BY u.id;

-- 使用视图
SELECT * FROM user_post_count ORDER BY cnt DESC;

-- 触发器：记录删除操作
CREATE TABLE delete_log (
  table_name TEXT,
  old_id     INTEGER,
  deleted_at TEXT DEFAULT (datetime('now'))
);

CREATE TRIGGER log_user_delete AFTER DELETE ON users
BEGIN
  INSERT INTO delete_log (table_name, old_id) VALUES ('users', OLD.id);
END;

-- 开启 WAL 模式（每次连接设置一次）
PRAGMA journal_mode=WAL;

-- 设置忙等待超时（毫秒）
PRAGMA busy_timeout=5000;

-- 显式事务
BEGIN IMMEDIATE;  -- 立即获取写锁
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- 查看日志模式
PRAGMA journal_mode;

-- 常用优化配置
PRAGMA journal_mode=WAL;
PRAGMA synchronous=NORMAL;
PRAGMA cache_size=-16000;   -- 16MB 缓存
PRAGMA temp_store=MEMORY;
PRAGMA foreign_keys=ON;
PRAGMA busy_timeout=3000;

-- 查看当前配置
PRAGMA database_list;
PRAGMA page_count;
PRAGMA page_size;

-- 数据库完整性检查
PRAGMA integrity_check;

-- 创建 FTS5 虚拟表
CREATE VIRTUAL TABLE posts_fts USING fts5(title, body);

-- 插入数据（同时插入到原表和 FTS 表）
INSERT INTO posts_fts SELECT title, body FROM posts;

-- 搜索
SELECT * FROM posts_fts WHERE posts_fts MATCH 'hello world';

-- 带排名
SELECT *, rank FROM posts_fts
WHERE posts_fts MATCH 'hello'
ORDER BY rank;

-- 布尔搜索
SELECT * FROM posts_fts
WHERE posts_fts MATCH '"image processing" OR "computer vision"';

const Database = require('better-sqlite3');
const db = new Database('app.db');
db.pragma('journal_mode = WAL');

db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id    INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  done  INTEGER DEFAULT 0
)`);

// 插入
const stmt = db.prepare('INSERT INTO tasks (title) VALUES (?)');
stmt.run('Buy milk');
stmt.run('Write code');

// 查询
const rows = db.prepare('SELECT * FROM tasks WHERE done=0').all();
console.log(rows);

// 事务批量插入
const insert = db.prepare('INSERT INTO tasks (title) VALUES (?)');
const tx = db.transaction((titles) => {
  for (const t of titles) insert.run(t);
});
tx(['Task1', 'Task2', 'Task3']);

-- 知识库完整 Schema
CREATE TABLE notes (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  title      TEXT NOT NULL,
  body       TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE tags (
  id   INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE note_tags (
  note_id INTEGER REFERENCES notes(id) ON DELETE CASCADE,
  tag_id  INTEGER REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (note_id, tag_id)
);

-- 全文搜索
CREATE VIRTUAL TABLE notes_fts USING fts5(title, body, content=notes, content_rowid=id);

-- 触发器：更新后自动同步 FTS
CREATE TRIGGER notes_ai AFTER INSERT ON notes BEGIN
  INSERT INTO notes_fts(rowid, title, body) VALUES (new.id, new.title, new.body);
END;

-- 查询：带标签过滤的搜索
SELECT n.id, n.title, GROUP_CONCAT(t.name) AS tags
FROM notes n
LEFT JOIN note_tags nt ON n.id = nt.note_id
LEFT JOIN tags t ON nt.tag_id = t.id
WHERE n.id IN (
  SELECT rowid FROM notes_fts WHERE notes_fts MATCH 'sqlite database'
)
GROUP BY n.id;
